manifest_content:
[workspace]
members = [
    "crates/buzz-relay",
    "crates/buzz-core",
    "crates/ifc-core",
    "crates/buzz-conformance",
    "crates/buzz-push-gateway",
    "crates/buzz-db",
    "crates/buzz-pubsub",
    "crates/buzz-auth",
    "crates/buzz-search",
    "crates/buzz-audit",
    "crates/buzz-acp",
    "crates/buzz-agent",
    "crates/sprig",
    "crates/buzz-test-client",
    "crates/buzz-ws-client",
    "crates/buzz-admin",
    "crates/buzz-deletion",
    "crates/buzz-feature-flags",
    "crates/buzz-workflow",
    "crates/buzz-media",
    "crates/buzz-cli",
    "crates/buzz-pairing-cli",
    "crates/buzz-sdk",
    "crates/buzz-persona",
    "crates/git-credential-nostr",
    "crates/git-sign-nostr",
    "crates/buzz-pair-relay",
    "crates/buzz-relay-mesh",
    "crates/buzz-mesh-smoke",
    "crates/buzz-dev-mcp",
    "crates/buzz-voice",
    "crates/buzz-backend-kubernetes",
    "crates/buzz-datastore-tracing",
    "examples/countdown-bot",
]
exclude = ["desktop/src-tauri"]
resolver = "2"

[workspace.package]
version = "0.1.0"
edition = "2021"
rust-version = "1.88.0"
license = "Apache-2.0"
repository = "https://github.com/block/sprout"

[workspace.dependencies]
# Runtime
tokio       = { version = "1", features = ["rt-multi-thread", "macros", "net", "time", "sync", "io-util", "signal", "process"] }
tokio-util  = { version = "0.7", features = ["rt", "codec"] }

# HTTP + WebSocket
axum        = { version = "0.8", features = ["ws", "macros"] }
tower       = { version = "0.5", features = ["timeout", "util", "limit"] }
tower-http  = { version = "0.6", features = ["trace", "cors", "compression-gzip", "limit", "timeout", "fs"] }

# Database
sqlx = { version = "0.9", features = [
    "runtime-tokio", "tls-rustls", "postgres", "uuid", "chrono", "json"
] }

# Redis
redis        = { version = "1.0", features = ["tokio-comp", "connection-manager", "tokio-rustls-comp"] }
deadpool-redis = { version = "0.23", features = ["rt_tokio_1"] }

# Kubernetes (buzz-backend-kubernetes provider). No `ring` feature here: the
# process-level CryptoProvider is installed explicitly at startup, matching
# buzz-cli/buzz-acp/buzz-admin/buzz-relay/buzz-dev-mcp — see the comment on the
# crate's own rustls dependency.
kube = { version = "2.0", default-features = false, features = ["client", "rustls-tls"] }
k8s-openapi = { version = "0.26", features = ["v1_31"] }

# Nostr
nostr = { version = "0.44", features = ["nip44", "nip98"] }

# Serialization
serde       = { version = "1", features = ["derive"] }
postcard    = { version = "1", default-features = false, features = ["use-std"] }

# Inter-relay mesh transport (buzz-relay-mesh)
iroh = { version = "1.0.0-rc.0", default-features = false, features = ["tls-ring"] }
serde_json  = { version = "1", features = ["raw_value"] }
serde_yaml  = "0.9"
evalexpr    = "11"
cron        = "0.16"
# Observability
tracing                     = "0.1"
tracing-subscriber          = { version = "0.3", features = ["env-filter", "json"] }
tracing-opentelemetry       = { version = "0.33" }
opentelemetry               = { version = "0.32", features = ["trace"] }
opentelemetry_sdk           = { version = "0.32", features = ["trace", "rt-tokio"] }
opentelemetry-otlp          = { version = "0.32", default-features = false, features = ["trace", "grpc-tonic", "tls-ring"] }
metrics             = "0.24"
metrics-exporter-prometheus = "0.18"
metrics-util        = "0.20"

# Error handling
thiserror = "2"
anyhow    = "1"

# Utilities
uuid    = { version = "1", features = ["v4", "serde"] }
chrono  = { version = "0.4", features = ["serde"] }

# JWT / JWS verification (NIP-FI federated identity assertions)
jsonwebtoken = { version = "10.4.0", default-features = false, features = ["aws_lc_rs"] }

# HTTP client (webhook delivery)
reqwest = { version = "0.13", features = ["json", "rustls", "stream"], default-features = false }

# Cryptography
sha2      = "0.11"
hex       = "0.4"
hmac      = "0.13"
base64    = "0.22"

# Randomness
rand = "0.10"
subtle = "2.6"
zeroize = "1.8"

# Concurrent data structures
dashmap = "6"
moka    = { version = "0.12", features = ["sync"] }

# Async stream utilities
futures-util = "0.3"

# WebSocket client (test client)
tokio-tungstenite = { version = "0.29", features = ["rustls-tls-webpki-roots"] }
url = "2"

# Property-based testing (dev-only)
proptest = "1"

# MCP SDK (used by buzz-dev-mcp and buzz-agent)
rmcp = { version = "1.1.0", features = ["server", "transport-io", "macros"] }
schemars = { version = "1", default-features = false }

# Internal crates
buzz-core = { path = "crates/buzz-core" }
buzz-conformance = { path = "crates/buzz-conformance" }
buzz-db = { path = "crates/buzz-db" }
buzz-deletion = { path = "crates/buzz-deletion" }
buzz-feature-flags = { path = "crates/buzz-feature-flags" }
buzz-auth = { path = "crates/buzz-auth" }
buzz-pubsub = { path = "crates/buzz-pubsub" }
buzz-search = { path = "crates/buzz-search" }
buzz-audit = { path = "crates/buzz-audit" }
buzz-workflow = { path = "cra

[workspace]
members = ["crates/*"]
exclude = [
  "scripts",
  # Needs nightly
  "crates/uv-trampoline",
]
resolver = "2"

[workspace.package]
edition = "2024"
rust-version = "1.96.0"
homepage = "https://pypi.org/project/uv/"
repository = "https://github.com/astral-sh/uv"
authors = ["uv"]
license = "MIT OR Apache-2.0"

[workspace.dependencies]
uv = { version = "0.12.19", path = "crates/uv", default-features = false }
uv-audit = { version = "0.0.86", path = "crates/uv-audit" }
uv-auth = { version = "0.0.86", path = "crates/uv-auth" }
uv-bin-install = { version = "0.0.86", path = "crates/uv-bin-install" }
uv-build-backend = { version = "0.0.86", path = "crates/uv-build-backend" }
uv-build-frontend = { version = "0.0.86", path = "crates/uv-build-frontend" }
uv-cache = { version = "0.0.86", path = "crates/uv-cache" }
uv-cache-info = { version = "0.0.86", path = "crates/uv-cache-info" }
uv-cache-key = { version = "0.0.86", path = "crates/uv-cache-key" }
uv-cli = { version = "0.0.86", path = "crates/uv-cli" }
uv-client = { version = "0.0.86", path = "crates/uv-client" }
uv-configuration = { version = "0.0.86", path = "crates/uv-configuration" }
uv-console = { version = "0.0.86", path = "crates/uv-console" }
uv-dirs = { version = "0.0.86", path = "crates/uv-dirs" }
uv-dispatch = { version = "0.0.86", path = "crates/uv-dispatch" }
uv-distribution = { version = "0.0.86", path = "crates/uv-distribution" }
uv-distribution-filename = { version = "0.0.86", path = "crates/uv-distribution-filename" }
uv-distribution-types = { version = "0.0.86", path = "crates/uv-distribution-types" }
uv-errors = { version = "0.0.86", path = "crates/uv-errors" }
uv-extract = { version = "0.0.86", path = "crates/uv-extract" }
uv-fastid = { version = "0.0.86", path = "crates/uv-fastid" }
uv-flags = { version = "0.0.86", path = "crates/uv-flags" }
uv-fs = { version = "0.0.86", path = "crates/uv-fs", features = [
  "serde",
  "tokio",
] }
uv-git = { version = "0.0.86", path = "crates/uv-git" }
uv-git-types = { version = "0.0.86", path = "crates/uv-git-types" }
uv-globfilter = { version = "0.0.86", path = "crates/uv-globfilter" }
uv-install-wheel = { version = "0.0.86", path = "crates/uv-install-wheel", default-features = false }
uv-installer = { version = "0.0.86", path = "crates/uv-installer" }
uv-keyring = { version = "0.0.86", path = "crates/uv-keyring" }
uv-lock = { version = "0.0.86", path = "crates/uv-lock" }
uv-logging = { version = "0.0.86", path = "crates/uv-logging" }
uv-macros = { version = "0.0.86", path = "crates/uv-macros" }
uv-metadata = { version = "0.0.86", path = "crates/uv-metadata" }
uv-netrc = { version = "0.0.86", path = "crates/uv-netrc" }
uv-normalize = { version = "0.0.86", path = "crates/uv-normalize" }
uv-once-map = { version = "0.0.86", path = "crates/uv-once-map" }
uv-options-metadata = { version = "0.0.86", path = "crates/uv-options-metadata" }
uv-performance-memory-allocator = { version = "0.0.86", path = "crates/uv-performance-memory-allocator" }
uv-pep440 = { version = "0.0.86", path = "crates/uv-pep440", features = [
  "tracing",
  "rkyv",
  "version-ranges",
] }
uv-pep508 = { version = "0.0.86", path = "crates/uv-pep508", features = [
  "non-pep508-extensions",
] }
uv-platform = { version = "0.0.86", path = "crates/uv-platform" }
uv-platform-tags = { version = "0.0.86", path = "crates/uv-platform-tags" }
uv-preview = { version = "0.0.86", path = "crates/uv-preview" }
uv-publish = { version = "0.0.86", path = "crates/uv-publish" }
uv-pypi-types = { version = "0.0.86", path = "crates/uv-pypi-types" }
uv-python = { version = "0.0.86", path = "crates/uv-python" }
uv-redacted = { version = "0.0.86", path = "crates/uv-redacted" }
uv-requirements = { version = "0.0.86", path = "crates/uv-requirements" }
uv-requirements-txt = { version = "0.0.86", path = "crates/uv-requirements-txt" }
uv-resolver = { version = "0.0.86", path = "crates/uv-resolver" }
uv-resolver-types = { version = "0.0.86", path = "crates/uv-resolver-types" }
uv-scripts = { version = "0.0.86", path = "crates/uv-scripts" }
uv-settings = { version = "0.0.86", path = "crates/uv-settings" }
uv-shell = { version = "0.0.86", path = "crates/uv-shell" }
uv-small-str = { version = "0.0.86", path = "crates/uv-small-str" }
uv-state = { version = "0.0.86", path = "crates/uv-state" }
uv-static = { version = "0.0.86", path = "crates/uv-static" }
uv-test = { version = "0.0.86", path = "crates/uv-test" }
uv-threads = { version = "0.0.86", path = "crates/uv-threads" }
uv-toml = { version = "0.0.86", path = "crates/uv-toml" }
uv-tool = { version = "0.0.86", path = "crates/uv-tool" }
uv-torch = { version = "0.0.86", path = "crates/uv-torch" }
uv-trampoline-builder = { version = "0.0.86", path = "crates/uv-trampoline-builder" }
uv-types = { version = "0.0.86", path = "crates/uv-types" }
uv-unix = { version = "0.0.86", path = "crates/uv-unix" }
uv-version = { version = "0.12.19", path = "crates/uv-version" }
uv-virtualenv = { version = "0.0.86", path = "crates/uv-virtual

{
  "name": "fastapi-full-stack-template",
  "private": true,
  "workspaces": [
    "frontend",
    "packages/*"
  ],
  "scripts": {
    "dev": "bun run --filter frontend dev",
    "lint": "bun run --filter frontend lint",
    "test": "bun run --filter frontend test",
    "test:ui": "bun run --filter frontend test:ui",
    "email:dev": "bun run --filter emails dev",
    "email:export": "bun run --filter emails export"
  }
}

{
  "name": "pi-claude-bridge",
  "version": "0.8.0",
  "private": false,
  "description": "Pi extension that uses Claude Code (via Agent SDK) as a model provider and adds an AskClaude tool.",
  "keywords": [
    "pi-package",
    "pi",
    "extension",
    "claude-code",
    "claude-agent-sdk"
  ],
  "author": "Eli Dickinson",
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/elidickinson/pi-claude-bridge.git"
  },
  "engines": {
    "node": ">=20"
  },
  "files": [
    "src",
    "README.md",
    "LICENSE",
    "assets"
  ],
  "scripts": {
    "test:unit": "node --import tsx --import ./tests/lib/setup.mjs --test tests/unit-*.mjs",
    "test": "set -a && [ -f .env.test ] && . .env.test; set +a && npm run test:unit && tests/int-smoke.sh && tests/int-multi-turn.sh && tests/int-cache.sh && node --import tsx --test tests/int-*.mjs",
    "test:usage": "tests/usage-test.sh",
    "typecheck": "tsc --noEmit"
  },
  "type": "module",
  "dependencies": {
    "@anthropic-ai/claude-agent-sdk": "^0.3.280",
    "@modelcontextprotocol/sdk": "^1.29.0",
    "cc-session-io": "^0.4.0",
    "change-case": "^5.4.4"
  },
  "peerDependencies": {
    "@earendil-works/pi-ai": ">=0.86.1",
    "@earendil-works/pi-coding-agent": ">=0.86.1",
    "@earendil-works/pi-tui": ">=0.86.1",
    "typebox": "*"
  },
  "devDependencies": {
    "@anthropic-ai/sdk": "^0.124.0",
    "@earendil-works/pi-ai": "^0.87.1",
    "@earendil-works/pi-coding-agent": "^0.87.1",
    "@earendil-works/pi-tui": "^0.87.1",
    "@types/node": "^24.13.2",
    "tsx": "^4.22.4",
    "typebox": "^1.3.7",
    "typescript": "^6.0.3"
  },
  "pi": {
    "extensions": [
      "./src/index.ts"
    ]
  }
}

{
  "name": "reversa",
  "version": "1.3.3",
  "description": "Transform legacy systems into executable specifications for AI coding agents",
  "bin": {
    "reversa": "bin/reversa.js"
  },
  "type": "module",
  "scripts": {
    "verify": "python3 scripts/verify-invocation.py && node scripts/test-installer-transport.mjs"
  },
  "keywords": [
    "legacy",
    "reverse-engineering",
    "specifications",
    "ai",
    "claude",
    "codex",
    "gemini",
    "cursor",
    "agents"
  ],
  "files": [
    "agents/",
    "bin/",
    "lib/",
    "templates/",
    "README.md",
    "LICENSE"
  ],
  "author": "sandeco",
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/sandeco/reversa.git"
  },
  "homepage": "https://github.com/sandeco/reversa",
  "bugs": {
    "url": "https://github.com/sandeco/reversa/issues"
  },
  "engines": {
    "node": ">=18.20.2"
  },
  "dependencies": {
    "chalk": "^5.3.0",
    "inquirer": "^9.2.0",
    "ora": "^7.0.1",
    "semver": "^7.6.0"
  }
}
